SELECT strftime(p.OrderDate,'%Y-%m') AS Month,COUNT(*) AS EligibleLines,COUNT(*) FILTER(WHERE l.LastReceiptDate>p.ExpectedDeliveryDate) AS LateLines FROM raw.Purchasing_PurchaseOrders p JOIN raw.Purchasing_PurchaseOrderLines l USING(PurchaseOrderID) WHERE l.IsOrderLineFinalized AND l.ReceivedOuters=l.OrderedOuters AND l.LastReceiptDate IS NOT NULL AND p.ExpectedDeliveryDate IS NOT NULL GROUP BY 1 ORDER BY 1